/**
 * Repoints every issue carrying `sourceLabelId` to `targetLabelId` and drops
 * the source label. Issues that already carry both end up with just the
 * target, so the join table's unique (issue_id, label_id) index is never hit.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();

  const sourceRows = db
    .select({ issueId: issueLabels.issueId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .all();
  const issuesRelabelled = sourceRows.length;

  if (issuesRelabelled > 0) {
    const targetRows = db
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, targetLabelId),
        ),
      )
      .all();
    const alreadyTargeted = new Set(targetRows.map((row) => row.issueId));

    const toInsert = sourceRows
      .map((row) => row.issueId)
      .filter((issueId) => !alreadyTargeted.has(issueId));

    if (toInsert.length > 0) {
      db.insert(issueLabels)
        .values(
          toInsert.map((issueId) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .run();
    }
  }

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .run();
  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
    .run();

  return issuesRelabelled;
}

